class Solution:
    def kthLargestPerfectSubtree(self, root: Optional[TreeNode], k: int) -> int:
        sizes = []
        def dfs(nd):
            if not nd:
                return 0
            l, r = dfs(nd.left), dfs(nd.right)
            if l < 0 or r < 0 or l != r:
                return -1
            sizes.append(l + r + 1)
            return l + r + 1
        dfs(root)
        sizes.sort(reverse=True)
        return sizes[k-1] if len(sizes) >= k else -1

