class Solution:
    def kthLargestPerfectSubtree(self, root: Optional[TreeNode], k: int) -> int:
        import heapq
        h = []
        def dfs(nd):
            if not nd:
                return 0
            l, r = dfs(nd.left), dfs(nd.right)
            if l < 0 or r < 0 or l != r:
                return -1
            s = l + r + 1
            heapq.heappush(h, s)
            if len(h) > k:
                heapq.heappop(h)
            return s
        dfs(root)
        return h[0] if len(h) == k else -1

