class Solution {
    PriorityQueue<Integer> h = new PriorityQueue<>();
    int k;
    int dfs(TreeNode nd) {
        if (nd == null) return 0;
        int l = dfs(nd.left), r = dfs(nd.right);
        if (l < 0 || r < 0 || l != r) return -1;
        int s = l + r + 1;
        h.offer(s);
        if (h.size() > k) h.poll();
        return s;
    }
    public int kthLargestPerfectSubtree(TreeNode root, int k_) {
        k = k_;
        dfs(root);
        return h.size() == k ? h.peek() : -1;
    }
}

