var kthLargestPerfectSubtree = function(root, k) {
    const h = [];
    const push = (x) => { h.push(x); let i = h.length - 1;
        while (i > 0) { const p = (i-1)>>1; if (h[i] < h[p]) { [h[i],h[p]]=[h[p],h[i]]; i=p; } else break; } };
    const pop = () => { const t = h[0], l = h.pop();
        if (h.length) { h[0] = l; let i = 0;
            for (;;) { let c = 2*i+1; if (c >= h.length) break;
                if (c+1 < h.length && h[c+1] < h[c]) c++;
                if (h[c] < h[i]) { [h[i],h[c]]=[h[c],h[i]]; i=c; } else break; } }
        return t; };
    function dfs(nd) {
        if (!nd) return 0;
        const l = dfs(nd.left), r = dfs(nd.right);
        if (l < 0 || r < 0 || l !== r) return -1;
        const s = l + r + 1;
        push(s);
        if (h.length > k) pop();
        return s;
    }
    dfs(root);
    return h.length === k ? h[0] : -1;
};
